{
  "campaign_name": "Campanha Teste Texto",
  "account": "{{account_id}}",
  "messages": [
    {
      "number": "{{phone_number}}",
      "vars": {
        "nome": "João Silva",
        "produto": "Smartphone XYZ",
        "preco": "R$ 1.299,00"
      }
    }
  ],
  "content": {
    "text": {
      "message": "Olá {{nome}}! Seu {{produto}} está disponível por {{preco}}. Aproveite!"
    }
  },
  "callback": "https://webhook.exemplo.com/callback",
  "fallback": [
    {
      "channel": "SMS",
      "content": "Ola {{nome}}! Seu {{produto}} esta disponivel por {{preco}}. Aproveite!"
    }
  ]
}

{
  "campaign_name": "Campanha Imagem",
  "account": "{{account_id}}",
  "messages": [
    {
      "number": "{{phone_number}}",
      "vars": {
        "nome": "Maria",
        "desconto": "30"
      }
    }
  ],
  "content": {
    "image": {
      "fileUrl": "https://picsum.photos/600/400",
      "message": "🎉 Olá {{nome}}! {{desconto}}% de desconto especial para você!"
    }
  },
  "callback": "https://webhook.exemplo.com/callback"
}

{
  "account": "{{account_id}}",
  "messages": [
    {
      "number": "{{phone_number}}"
    }
  ],
  "content": {
    "richCard": {
      "title": "🎉 Oferta Especial!",
      "description": "Aproveite 25% de desconto em todos os smartphones. Oferta válida até o final do mês!",
      "fileUrl": "https://picsum.photos/600/400?random=1",
      "suggestions": [
        {
          "type": "openUrl",
          "title": "Ver Produtos",
          "value": "https://loja.exemplo.com/smartphones"
        },
        {
          "type": "call",
          "title": "Ligar Agora",
          "value": "1140001234"
        },
        {
          "type": "reply",
          "title": "Tenho Interesse",
          "value": "interesse_smartphones"
        }
      ]
    }
  }
}

{
  "account": "{{account_id}}",
  "messages": [
    {
      "number": "{{phone_number}}"
    }
  ],
  "content": {
    "carousel": {
      "cards": [
        {
          "title": "iPhone 15 Pro",
          "description": "O mais avançado iPhone com chip A17 Pro e câmera de 48MP.",
          "fileUrl": "https://picsum.photos/400/300?random=2",
          "suggestions": [
            {
              "type": "openUrl",
              "title": "Comprar",
              "value": "https://loja.exemplo.com/iphone15"
            },
            {
              "type": "reply",
              "title": "Mais Info",
              "value": "info_iphone15"
            }
          ]
        },
        {
          "title": "Samsung Galaxy S24",
          "description": "Galaxy AI revolucionário com câmera de 200MP e tela Dynamic AMOLED.",
          "fileUrl": "https://picsum.photos/400/300?random=3",
          "suggestions": [
            {
              "type": "openUrl",
              "title": "Comprar",
              "value": "https://loja.exemplo.com/galaxy-s24"
            },
            {
              "type": "reply",
              "title": "Mais Info",
              "value": "info_galaxy_s24"
            }
          ]
        },
        {
          "title": "Xiaomi 14 Ultra",
          "description": "Fotografia profissional com lentes Leica e Snapdragon 8 Gen 3.",
          "fileUrl": "https://picsum.photos/400/300?random=4",
          "suggestions": [
            {
              "type": "openUrl",
              "title": "Comprar",
              "value": "https://loja.exemplo.com/xiaomi-14"
            },
            {
              "type": "reply",
              "title": "Mais Info",
              "value": "info_xiaomi_14"
            }
          ]
        }
      ]
    }
  }
}

{
  "account": "{{account_id}}",
  "messages": [
    {
      "number": "{{phone_number}}"
    }
  ],
  "content": {
    "suggestion": {
      "message": "Como posso ajudá-lo hoje? Escolha uma das opções abaixo:",
      "suggestions": [
        {
          "type": "reply",
          "title": "Ver Produtos",
          "value": "produtos"
        },
        {
          "type": "reply",
          "title": "Suporte",
          "value": "suporte"
        },
        {
          "type": "reply",
          "title": "Promoções",
          "value": "promocoes"
        },
        {
          "type": "call",
          "title": "Ligar",
          "value": "1140001234"
        }
      ]
    }
  }
}

{
  "account": "{{account_id}}",
  "webhook": "https://webhook.exemplo.com/rcs-responses",
  "messages": [
    {
      "number": "{{phone_number}}"
    }
  ],
  "content": {
    "text": {
      "message": "Olá! Sou seu assistente virtual. Como posso ajudá-lo hoje? Digite sua dúvida ou escolha uma opção."
    }
  }
}

{
  "account": "{{account_id}}",
  "webhook": "https://webhook.exemplo.com/rcs-responses",
  "messages": [
    {
      "number": "{{phone_number}}"
    }
  ],
  "content": {
    "richCard": {
      "title": "🛍️ Central de Atendimento",
      "description": "Escolha como deseja ser atendido. Nossa equipe está pronta para ajudar!",
      "fileUrl": "https://picsum.photos/600/400?random=5",
      "suggestions": [
        {
          "type": "reply",
          "title": "Falar com Vendedor",
          "value": "vendedor"
        },
        {
          "type": "reply",
          "title": "Suporte Técnico",
          "value": "suporte"
        },
        {
          "type": "reply",
          "title": "Financeiro",
          "value": "financeiro"
        },
        {
          "type": "call",
          "title": "Ligar Direto",
          "value": "1140001234"
        }
      ]
    }
  }
}

{
  "name": "Boas Vindas Personalizado",
  "account": "{{account_id}}",
  "content_type": "text",
  "template_data": {
    "message": "🎉 Olá {{nome}}! Bem-vindo à {{empresa}}. Seu código de acesso é: {{codigo}}. Aproveite {{desconto}}% de desconto na primeira compra!"
  }
}

{
  "name": "Promoção Produto",
  "account": "{{account_id}}",
  "content_type": "richCard",
  "template_data": {
    "title": "🔥 {{produto}} em Promoção!",
    "description": "Aproveite {{desconto}}% OFF no {{produto}} por apenas {{preco}}! Oferta válida até {{data_limite}}.",
    "fileUrl": "{{imagem_produto}}",
    "suggestions": [
      {
        "type": "openUrl",
        "title": "Comprar Agora",
        "value": "{{link_compra}}"
      },
      {
        "type": "call",
        "title": "Falar com Vendedor",
        "value": "{{telefone_vendas}}"
      },
      {
        "type": "reply",
        "title": "Mais Informações",
        "value": "info_{{produto_id}}"
      }
    ]
  }
}

{
  "name": "Catálogo Produtos",
  "account": "{{account_id}}",
  "content_type": "carousel",
  "template_data": {
    "cards": [
      {
        "title": "{{produto1_nome}}",
        "description": "{{produto1_desc}} - Por apenas {{produto1_preco}}",
        "fileUrl": "{{produto1_imagem}}",
        "suggestions": [
          {
            "type": "openUrl",
            "title": "Ver Detalhes",
            "value": "{{produto1_link}}"
          }
        ]
      },
      {
        "title": "{{produto2_nome}}",
        "description": "{{produto2_desc}} - Por apenas {{produto2_preco}}",
        "fileUrl": "{{produto2_imagem}}",
        "suggestions": [
          {
            "type": "openUrl",
            "title": "Ver Detalhes",
            "value": "{{produto2_link}}"
          }
        ]
      },
      {
        "title": "{{produto3_nome}}",
        "description": "{{produto3_desc}} - Por apenas {{produto3_preco}}",
        "fileUrl": "{{produto3_imagem}}",
        "suggestions": [
          {
            "type": "openUrl",
            "title": "Ver Detalhes",
            "value": "{{produto3_link}}"
          }
        ]
      }
    ]
  }
}
